class Solution {
public:
    vector<string> removeAnagrams(vector<string>& words) {
        vector<string> result;
        int lastFreq[26] = {};
        int n = words.size();
        for (int idx = 0; idx < n; idx++) {
            const string& w = words[idx];
            int freq[26] = {};
            for (char c : w) freq[c - 'a']++;
            bool same = false;
            if (idx > 0) {
                same = true;
                for (int i = 0; i < 26; i++) {
                    if (freq[i] != lastFreq[i]) { same = false; break; }
                }
            }
            if (!same) {
                result.push_back(w);
                for (int i = 0; i < 26; i++) lastFreq[i] = freq[i];
            }
        }
        return result;
    }
};
